import { useState, useEffect, useMemo } from "react";
import { MapContainer, TileLayer, Popup, useMapEvents, GeoJSON, useMap, Tooltip } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';
import L from 'leaflet';
import { useNavigate } from "react-router-dom";
import "../styles/AdminDashboard.css";

// --- Component điều khiển Map ---
function MapController({ zones, selectedDistrict, districts }) {
  const map = useMap();
  useEffect(() => {
    if (!zones || zones.length === 0) {
      if (selectedDistrict) {
        const dist = districts.find(d => d.id === selectedDistrict);
        if (dist && dist.center_lat) map.flyTo([dist.center_lat, dist.center_lng], 13);
      }
      return;
    }
    const bounds = [];
    zones.forEach(z => {
      if (z.center_lat && z.center_lng) bounds.push([z.center_lat, z.center_lng]);
      if (z.geometry?.coordinates) {
        try {
          const coords = z.geometry.type === 'Polygon' ? z.geometry.coordinates[0] : z.geometry.coordinates[0][0];
          coords.forEach(c => bounds.push([c[1], c[0]]));
        } catch(e) {}
      }
    });
    if (bounds.length > 0) map.fitBounds(L.latLngBounds(bounds), { padding: [50, 50] });
  }, [zones, selectedDistrict, map, districts]);
  return null;
}

const API_BASE = "http://localhost:8000";

export default function AdminDashboard() {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState("zones");
  const [districts, setDistricts] = useState([]);
  const [allZones, setAllZones] = useState([]);
  const [selectedDistrict, setSelectedDistrict] = useState(null);
  
  // State cho Form
  const [showDistrictForm, setShowDistrictForm] = useState(false);
  const [editingZone, setEditingZone] = useState(null); // Zone đang được chỉnh sửa
  const [newDistrict, setNewDistrict] = useState({ code: "", name: "", center_lat: 21.0285, center_lng: 105.8542 });

  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  useEffect(() => {
    fetchDistricts();
    fetchAllZones();
  }, []);

  const fetchDistricts = async () => {
    const res = await fetch(`${API_BASE}/districts`);
    setDistricts(await res.json());
  };

  const fetchAllZones = async () => {
    const res = await fetch(`${API_BASE}/zones`);
    setAllZones(await res.json());
  };

  // --- Xử lý Xóa Zone ---
  const handleDeleteZone = async (zoneId) => {
    if (!window.confirm("Bạn có chắc chắn muốn xóa Zone này?")) return;
    try {
      const res = await fetch(`${API_BASE}/zones/${zoneId}`, { method: "DELETE" });
      if (res.ok) {
        setSuccess("Xóa Zone thành công!");
        fetchAllZones(); // Reload dữ liệu
      }
    } catch (err) { setError("Lỗi khi xóa zone"); }
  };

  // --- Xử lý Cập nhật Zone (Thông tin khách hàng, đơn hàng...) ---
  const handleUpdateZone = async (e) => {
    e.preventDefault();
    try {
      const res = await fetch(`${API_BASE}/zones/${editingZone.id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: editingZone.name,
          num_customers: parseInt(editingZone.num_customers),
          num_orders: parseInt(editingZone.num_orders),
          revenue: parseFloat(editingZone.revenue)
        }),
      });
      if (res.ok) {
        setSuccess("Cập nhật thông tin Zone thành công!");
        setEditingZone(null);
        fetchAllZones();
      }
    } catch (err) { setError("Lỗi khi cập nhật zone"); }
  };

  const handleAddDistrict = async () => {
    const res = await fetch(`${API_BASE}/districts`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(newDistrict),
    });
    if (res.ok) {
      fetchDistricts();
      setShowDistrictForm(false);
      setSuccess("Thêm quận thành công");
    }
  };

  const displayedZones = useMemo(() => {
    return selectedDistrict ? allZones.filter(z => z.district_id === selectedDistrict) : allZones;
  }, [allZones, selectedDistrict]);

  const getZoneColor = (id) => `hsl(${(id * 137.5) % 360}, 70%, 50%)`;

  return (
    <div className="dashboard-container">
      <header className="dashboard-header">
        <div className="header-content">
          <h1>🏢 Quản lý Phân vùng & Zones</h1>
          <button className="logout-btn" onClick={() => navigate("/")}>Đăng xuất</button>
        </div>
      </header>

      <div className="dashboard-wrapper">
        <aside className="sidebar">
          <nav className="nav-menu">
            <button className={`nav-item ${activeTab === "zones" ? "active" : ""}`} onClick={() => setActiveTab("zones")}>📍 Quản lý Zones</button>
            <button className="nav-item" onClick={() => setSelectedDistrict(null)}>🌍 Xem Tất Cả</button>
          </nav>
        </aside>

        <main className="main-content">
          {success && <div className="success-message" onClick={() => setSuccess("")}>{success} [X]</div>}

          <div className="content-section">
            <div className="section-header">
              <h2>{selectedDistrict ? `Quận: ${districts.find(d=>d.id===selectedDistrict)?.name}` : "Tất cả các Phân vùng"}</h2>
              <button className="btn-primary" onClick={() => setShowDistrictForm(true)}>➕ Thêm Quận</button>
            </div>

            {/* Form Chỉnh sửa Zone (Modal/Overlay) */}
            {editingZone && (
              <div className="edit-overlay">
                <div className="edit-modal">
                  <h3>Chỉnh sửa Zone: {editingZone.zone_code}</h3>
                  <form onSubmit={handleUpdateZone}>
                    <label>Tên Zone:</label>
                    <input type="text" value={editingZone.name} onChange={e => setEditingZone({...editingZone, name: e.target.value})} />
                    
                    <label>Số khách hàng:</label>
                    <input type="number" value={editingZone.num_customers} onChange={e => setEditingZone({...editingZone, num_customers: e.target.value})} />
                    
                    <label>Số đơn hàng:</label>
                    <input type="number" value={editingZone.num_orders} onChange={e => setEditingZone({...editingZone, num_orders: e.target.value})} />
                    
                    <label>Doanh thu (VND):</label>
                    <input type="number" value={editingZone.revenue} onChange={e => setEditingZone({...editingZone, revenue: e.target.value})} />
                    
                    <div className="form-actions">
                      <button type="submit" className="btn-success">Lưu thay đổi</button>
                      <button type="button" className="btn-secondary" onClick={() => setEditingZone(null)}>Hủy</button>
                    </div>
                  </form>
                </div>
              </div>
            )}

            <div className="map-container" style={{ height: '500px', borderRadius: '12px', overflow: 'hidden', border: '1px solid #ccc' }}>
              <MapContainer center={[21.0285, 105.8542]} zoom={12} style={{ height: '100%' }}>
                <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />
                <MapController zones={displayedZones} selectedDistrict={selectedDistrict} districts={districts} />
                
                {displayedZones.map(z => (
                  <GeoJSON 
                    key={z.id} 
                    data={z.geometry} 
                    style={{ color: getZoneColor(z.id), fillOpacity: 0.5 }}
                    eventHandlers={{
                        click: () => setEditingZone(z) // Click vào map để mở form sửa
                    }}
                  >
                    <Tooltip permanent direction="center" className="zone-label">{z.name}</Tooltip>
                    <Popup>
                        <strong>{z.name}</strong><br/>
                        KH: {z.num_customers} | ĐH: {z.num_orders}
                    </Popup>
                  </GeoJSON>
                ))}
              </MapContainer>
            </div>

            {/* Bảng quản lý chi tiết */}
            <div className="zone-table-container" style={{ marginTop: '30px' }}>
              <h3>Chi tiết các Zone</h3>
              <table className="data-table">
                <thead>
                  <tr>
                    <th>Mã</th>
                    <th>Tên Phường/Xã</th>
                    <th>Khách hàng</th>
                    <th>Đơn hàng</th>
                    <th>Doanh thu</th>
                    <th>Thao tác</th>
                  </tr>
                </thead>
                <tbody>
                  {displayedZones.map(z => (
                    <tr key={z.id}>
                      <td>{z.zone_code}</td>
                      <td>{z.name}</td>
                      <td>{z.num_customers}</td>
                      <td>{z.num_orders}</td>
                      <td>{z.revenue.toLocaleString()}</td>
                      <td>
                        <button className="btn-edit" onClick={() => setEditingZone(z)}>✏️ Sửa</button>
                        <button className="btn-delete" onClick={() => handleDeleteZone(z.id)}>🗑️ Xóa</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        </main>
      </div>
    </div>
  );
}
